pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address randomEOA) public {
        // The fuzzer provides an arbitrary address, but to meaningfully test
        // the property we need a contract at a known address that reports the
        // real pool info (specifically the shutdown flag).  Since the P and M
        // differ only in the return of `isCvxShutdown`, which delegates to
        // `booster.poolInfo(cvxPoolInfo.pId).shutdown`, we deploy a minimal
        // stand-in for the ICVXBooster interface that the fuzzer can control.
        // We then invoke `setCvxPoolInfo` to point `c` at this fake booster.
        // The rule is: `isCvxShutdown()` == `fakeBooster.poolInfo(pid).shutdown`
        // for every possible shutdown status the booster can report.
        // The buggy code always returns `true`, so it will fail for the
        // case where `shutdown` is `false`.
        FakeBooster fakeBooster = new FakeBooster();

        // The owner of `c` is `address(this)`, so we can call `setCvxPoolInfo`.
        // Use a fuzzed pool id (bounded to avoid excessive array length).
        uint32 pid = uint32(bound(uint256(keccak256(abi.encode(randomEOA))), 0, 100));
        c.setCvxPoolInfo(pid, address(1), address(2));

        // Replace the booster storage with the fake booster's address.
        // Because `booster` is `immutable`, we cannot change the one set in the
        // constructor.  Therefore we need a fresh C contract that uses our fake
        // booster.  We redeploy `c` with the fake booster's address as the
        // `_booster` parameter.  The remaining constructor parameters are
        // irrelevant for this property test.
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(fakeBooster)), new address[](0));
        c.setCvxPoolInfo(pid, address(1), address(2));

        // Now we let the fuzzer decide whether the pool is shutdown (true/false).
        // We parse a boolean from the fuzzed address's parity.
        bool isShutdown = (uint160(randomEOA) & 1) == 1;
        fakeBooster.setShutdown(pid, isShutdown);

        // The property: `c.isCvxShutdown()` MUST equal the actual shutdown flag
        // we just set on the booster.  This holds for the correct C and fails
        // for the mutant when `isShutdown` is false (the bug always returns true).
        assertTrue(c.isCvxShutdown() == isShutdown);
    }
}

// Minimal adversarial helper that implements the subset of ICVXBooster used by
// `isCvxShutdown()`.  It lets the test control the `shutdown` flag per pool id.
contract FakeBooster {
    struct PoolInfo {
        address lptoken;
        address token;
        address gauge;
        address crvRewards;
        address stash;
        bool shutdown;
    }

    mapping(uint256 => PoolInfo) public poolInfo;

    function setShutdown(uint256 pid, bool shutdown) external {
        poolInfo[pid].shutdown = shutdown;
    }
}

