        // Set initial rewardsRecipient to some address
        c.setRewardsRecipient(address(0xdead));

        // Call setRewardsRecipient with the fuzzed newRecipient
        c.setRewardsRecipient(newRecipient);

        // Record balances before getReward
        uint256 balBeforeNew = token.balanceOf(newRecipient);
        uint256 balBeforeZeroDead = token.balanceOf(address(0xdead));

        // Trigger getReward - the mock token will call getReward on IBaseRewardPool which is now the token itself
        // The token's IBaseRewardPool interface methods are available
        token.setEarned(address(c), rewardAmount);
        c.getReward(false);

        // 3. Assert: rewardsRecipient() must match the address that received the tokens
        // If rewardsRecipient was updated, newRecipient received tokens; if not, 0xdead received them
        address currentRecipient = c.rewardsRecipient();
        uint256 balAfterNew = token.balanceOf(newRecipient);
        uint256 balAfterDead = token.balanceOf(address(0xdead));

        if (currentRecipient == newRecipient) {
            assertTrue(balAfterNew > balBeforeNew);
        } else {
            // It went to the old recipient, not the new one -> property violated
            assertTrue(balAfterDead > balBeforeDead);
        }
    }
}

contract MockToken is IERC20, IBaseRewardPool {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    uint256 private _totalSupply;
    mapping(address => uint256) private _earned;

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
        _totalSupply += amount;
        emit Transfer(address(0), to, amount);
    }

    function setEarned(address account, uint256 amount) external {
        _earned[account] = amount;
    }

    // IERC20
    function totalSupply() external view override returns (uint256) { return _totalSupply; }
    function balanceOf(address account) external view override returns (uint256) { return _balances[account]; }
    function transfer(address to, uint256 amount) external override returns (bool) {
        require(_balances[msg.sender] >= amount, "insufficient balance");
        _balances[msg.sender] -= amount;
        _balances[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }
    function allowance(address owner, address spender) external view override returns (uint256) {
        return _allowances[owner][spender];
    }
    function approve(address spender, uint256 amount) external override returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        require(_allowances[from][msg.sender] >= amount, "insufficient allowance");
        require(_balances[from] >= amount, "insufficient balance");
        _allowances[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    // IBaseRewardPool
    function withdrawAndUnwrap(uint256 amount, bool claim) external override returns (bool) {
        if (claim) {
            // Transfer reward tokens to caller
            uint256 earned = _earned[msg.sender];
            if (earned > 0) {
                _balances[msg.sender] += earned;
                _totalSupply += earned;
                _earned[msg.sender] = 0;
            }
        }
        return true;
    }
    function withdrawAll(bool claim) external override {
        withdrawAndUnwrap(_balances[msg.sender], claim);
    }
    function withdrawAllAndUnwrap(bool claim) external override {
        if (claim) {
            uint256 earned = _earned[msg.sender];
            if (earned > 0) {
                _balances[msg.sender] += earned;
                _totalSupply += earned;
                _earned[msg.sender] = 0;
            }
        }
    }
    function withdraw(uint256 amount, bool claim) external override {
        withdrawAndUnwrap(amount, claim);
    }
    function stakeFor(address _for, uint256 _amount) external override returns (bool) { return true; }
    function stakeAll() external override returns (bool) { return true; }
    function stake(uint256 _amount) external override returns (bool) { return true; }
    function earned(address account) external view override returns (uint256) { return _earned[account]; }
    function getReward(address _account, bool _claimExtras) external override returns (bool) {
        if (_claimExtras) {
            uint256 earnedAmt = _earned[_account];
            if (earnedAmt > 0) {
                _balances[_account] += earnedAmt;
                _totalSupply += earnedAmt;
                _earned[_account] = 0;
            }
        }
        return true;
    }
    function getReward() external override returns (bool) {
        return getReward(msg.sender, true);
    }
    function balanceOf(address account) external view override(IBaseRewardPool, IERC20) returns (uint256) {
        return _balances[account];
    }
    function rewardToken() external view override returns (address) { return address(this); }
}

interface IERC20 {
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IBaseRewardPool {
    function withdrawAndUnwrap(uint256 amount, bool claim) external returns (bool);
    function withdrawAll(bool claim) external;
    function withdrawAllAndUnwrap(bool claim) external;
    function withdraw(uint256 amount, bool claim) external;
    function stakeFor(address _for, uint256 _amount) external returns (bool);
    function stakeAll() external returns (bool);
    function stake(uint256 _amount) external returns (bool);
    function earned(address account) external view returns (uint256);
    function getReward(address _account, bool _claimExtras) external returns (bool);
    function getReward() external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function rewardToken() external view returns (address);
}

