import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // Booster parameter is 0 for now; we'll deploy a minimal Booster mock to answer poolInfo
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
    }

    function testFuzz_property(uint32 pId, bool shutdown, address token, address rewards) public {
        // Deploy a minimal Booster mock that records setCvxPoolInfo pId and returns the supplied shutdown flag
        BoosterMock booster = new BoosterMock(shutdown);
        c.setOperator(address(this));
        c.setCvxPoolInfo(pId, token, rewards);
        // Replace the booster with our mock by deploying a new C (since booster is immutable).
        // The only way to test isCvxShutdown behaviour with a configurable booster is to deploy C
        // with the mock booster address, then setCvxPoolInfo again.
        C testC = new C(address(this), IERC20(address(0)), ICVXBooster(address(booster)), new address[](0));
        testC.setCvxPoolInfo(pId, token, rewards);

        // The rule: isCvxShutdown() must equal the booster's reported shutdown flag.
        bool expectedShutdown = booster.poolInfo(pId).shutdown;
        bool actualShutdown = testC.isCvxShutdown();
        assertTrue(expectedShutdown == actualShutdown, "isCvxShutdown must match booster poolInfo(shutdown)");
    }
}

contract BoosterMock {
    bool public immutable shutdown;
    constructor(bool _shutdown) {
        shutdown = _shutdown;
    }

    function poolInfo(uint256) external view returns (address lptoken, address token, address gauge, address crvRewards, address stash, bool _shutdown) {
        return (address(0), address(0), address(0), address(0), address(0), shutdown);
    }
}

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function allowance(address, address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

interface ICVXBooster {
    struct PoolInfo {
        address lptoken;
        address token;
        address gauge;
        address crvRewards;
        address stash;
        bool shutdown;
    }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
}

