pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(uint256 amount, address operator) public {
        vm.assume(amount > 0);
        c.setOperator(operator);
        c.setCvxPoolInfo(0, address(0), address(0));
        bool ok;
        vm.prank(operator);
        try c.depositAndStake(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

