pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(new BoosterMock())), new address[](0)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        c.setCvxPoolInfo(0, address(0), address(0));
        uint256 allowanceBefore = IERC20(address(0)).allowance(address(c), address(new BoosterMock()));
        c.depositAndStake(amount);
        uint256 allowanceAfter = IERC20(address(0)).allowance(address(c), address(new BoosterMock()));
        assertTrue(allowanceBefore == allowanceAfter);
    }
}

contract BoosterMock {
    function poolInfo(uint256) external pure returns (ICVXBooster.PoolInfo memory) {
        return ICVXBooster.PoolInfo({
            lptoken: address(0),
            token: address(0),
            gauge: address(0),
            crvRewards: address(0),
            stash: address(0),
            shutdown: true
        });
    }
}

