pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ICVXBooster booster;

    function setUp() public {
        booster = ICVXBooster(address(new BoosterMock()));
        c = new C(address(this), IERC20(address(new ClpTokenMock())), booster, new address[](0));
        c.setCvxPoolInfo(0, address(0xdead), address(new RewardsMock()));
    }

    function testFuzz_property(bool isShutdown) public {
        // Set up the booster mock to reflect the fuzzed shutdown status
        BoosterMock(address(booster)).setShutdown(isShutdown);
        // c as operator to call depositAndStake
        vm.prank(address(this));
        c.depositAndStake(100);

        // After depositAndStake, if pool is shutdown, staked balance must be 0
        assertTrue(isShutdown ? c.stakedBalance() == 0 : c.stakedBalance() == 100);
    }
}

contract BoosterMock {
    bool public shutdown;
    function setShutdown(bool _shutdown) external { shutdown = _shutdown; }
    function poolInfo(uint256) external view returns (ICVXBooster.PoolInfo memory) {
        return ICVXBooster.PoolInfo({
            lptoken: address(0),
            token: address(0),
            gauge: address(0),
            crvRewards: address(0),
            stash: address(0),
            shutdown: shutdown
        });
    }
    function deposit(uint256, uint256, bool) external returns (bool) { return true; }
}

contract RewardsMock {
    uint256 private _balance;
    function stakeFor(address, uint256 _amount) external returns (bool) {
        _balance += _amount;
        return true;
    }
    function balanceOf(address) external view returns (uint256) { return _balance; }
    function withdrawAndUnwrap(uint256, bool) external returns (bool) { return true; }
    function withdrawAllAndUnwrap(bool) external {}
    function earned(address) external view returns (uint256) { return 0; }
    function getReward(address, bool) external returns (bool) { return true; }
    function rewardToken() external view returns (address) { return address(0); }
}

contract ClpTokenMock {
    mapping(address => uint256) private _allowances;
    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        return true;
    }
    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowances[owner][spender];
    }
    function transfer(address, uint256) external returns (bool) { return true; }
    function balanceOf(address) external view returns (uint256) { return 0; }
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface ICVXBooster {
    struct PoolInfo {
        address lptoken;
        address token;
        address gauge;
        address crvRewards;
        address stash;
        bool shutdown;
    }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
    function deposit(uint256 _pid, uint256 _amount, bool _stake) external returns (bool);
}
